return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sw','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-03T18:22:39+00:00','po-revision-date'=>'2026-09-03T18:22:39+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'Injini kamili ya uhifadhi wa akiba na uboreshaji kwa ajili ya WordPress: akiba ya ukurasa mzima, akiba ya vitu, usafishaji wa hifadhidata na uboreshaji wa CSS/JS. Sakinisha hii wakati mwenyeji wako hatoi safu yake ya akiba — kwenye mwenyeji wa Zinn Digital® sakinisha Zinn® Cache badala yake. Uhifadhi wa akiba wa ukurasa mzima unahitaji seva ya LiteSpeed au OpenLiteSpeed yenye moduli ya LSCache. Tawi la GPLv3 la programu-jalizi ya LiteSpeed Cache.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'Saa %d','%d hour'=>'Saa %d','%d minutes'=>'dakika %d','%d minute'=>'dakika %d','Purged All!'=>'Imefutwa Yote!','Purged the blog!'=>'Blogi imefutwa kabisa!','Purged the URL!'=>'Url imesafishwa!','Purged!'=>'Imesafishwa!','Failed to upgrade.'=>'Imeshindwa kuboresha.','Upgraded successfully.'=>'Imepandishwa daraja kwa mafanikio.','Dashboard'=>'Dashibodi','OptimaX'=>'OptimaX','Presets'=>'Violekeo Vilivyowekwa Awali','General'=>'Jumla','Cache'=>'Kache','CDN'=>'CDN','Image Optimization'=>'Uboreshaji wa Picha','Page Optimization'=>'Uboreshaji wa Kurasa','Data